"""Cliente de Cobrá, la pasarela de pagos. Cobrá es la fuente de verdad sobre el estado de un pago.

Cualquier respuesta que no esté en el contrato para esa ruta, o que no se pueda leer, es una falla
(CobraNoDisponible): nunca se interpreta como "el pago no existe".
"""
import os
from urllib.parse import quote

import httpx

ESTADOS = ('pendiente', 'aprobado', 'rechazado')
TIMEOUT_SEGUNDOS = 5
# Transporte de httpx a usar; None usa el de red. Los tests lo reemplazan por uno falso.
TRANSPORTE = None


class CobraNoDisponible(Exception):
    pass


def _pedido(metodo, ruta, aceptados, **kwargs):
    url = os.environ.get('PULSO_PAGOS_URL', '').rstrip('/') + ruta
    headers = {'X-Cobra-Clave': os.environ.get('PULSO_PAGOS_CLAVE', '')}
    headers.update(kwargs.pop('headers', {}))
    try:
        with httpx.Client(timeout=TIMEOUT_SEGUNDOS, transport=TRANSPORTE) as cliente:
            r = cliente.request(metodo, url, headers=headers, **kwargs)
    except httpx.HTTPError as error:
        raise CobraNoDisponible(f'No se pudo conectar con Cobrá: {error}') from error
    if r.status_code not in aceptados:
        raise CobraNoDisponible(f'Cobrá respondió {r.status_code} a {metodo} {ruta}')
    return r


def _leer_json(r):
    try:
        return r.json()
    except ValueError as error:
        raise CobraNoDisponible('Cobrá respondió algo que no es JSON') from error


def _pago(datos):
    if not isinstance(datos, dict) or not all(isinstance(datos.get(k), str) for k in ('id', 'estado', 'referencia')):
        raise CobraNoDisponible('Cobrá respondió un pago mal formado')
    if datos['estado'] not in ESTADOS:
        raise CobraNoDisponible(f"Cobrá respondió un estado desconocido: {datos['estado']}")
    return datos


def crear_pago(referencia, monto):
    """Crea el pago. Con la misma referencia, Cobrá devuelve el que ya existía (200) en vez de crear otro."""
    r = _pedido('POST', '/pagos', (200, 201), headers={'Idempotency-Key': referencia},
                json={'monto': monto, 'moneda': 'UYU', 'referencia': referencia})
    return _pago(_leer_json(r))


def obtener_pago(pago_id):
    """Devuelve el pago, o None si Cobrá no lo conoce."""
    r = _pedido('GET', f'/pagos/{quote(pago_id, safe="")}', (200, 404))
    if r.status_code == 404:
        return None
    return _pago(_leer_json(r))


def pagos_por_referencia(referencia):
    r = _pedido('GET', '/pagos', (200,), params={'referencia': referencia})
    datos = _leer_json(r)
    if not isinstance(datos, dict) or not isinstance(datos.get('pagos'), list):
        raise CobraNoDisponible('Cobrá respondió una lista de pagos mal formada')
    return [_pago(p) for p in datos['pagos']]
EOF
